<?php require dirname(__DIR__).'/app/bootstrap.php'; require dirname(__DIR__).'/app/layout.php';
$products=db()->query('SELECT * FROM products ORDER BY created_at DESC, productId DESC LIMIT 3')->fetchAll();$photosByProduct=photosForProducts($products);$available=availableInventory(db(),array_column($products,'productId'));pageStart('Home'); ?>
<section class="hero"><h1>Make your event unforgettable</h1><p>Rent glassware and event essentials for your next celebration.</p><a class="button" href="/products.php">Browse rental products</a></section><h2>Featured rentals</h2>
<div class="grid"><?php foreach($products as $p): ?><article class="card"><?php $gallery=galleryForProduct($p,$photosByProduct);$first=$gallery[0]['thumbnail_url']??photoUrl($p['photo_key']);if($first): ?><img src="<?= e($first) ?>" alt="<?= e($p['name']) ?>"><?php endif; ?><h3><?= e($p['name']) ?></h3><p><?= e($p['description']) ?></p><?php if($p['size']!=='' || $p['color']!=='' || $p['material']!==''):?><p class="product-attributes"><?php foreach(['size'=>'Size','color'=>'Color','material'=>'Material'] as $key=>$label): if($p[$key]!==''):?><span><strong><?=e($label)?>:</strong> <?=e($p[$key])?></span><?php endif; endforeach;?></p><?php endif;?><strong>$<?= number_format((float)$p['price'],2) ?> / 14-day rental</strong><p class="quantity">Available: <?= number_format($available[(int)$p['productId']]??0) ?></p><?php if(($available[(int)$p['productId']]??0)===0): ?><p class="error"><strong>Unavailable</strong></p><?php endif; ?></article><?php endforeach; ?></div><?php pageEnd();
